  "。 桌面桥只调用宿主预加载层明确暴露的白名单对象，不开放 Node 全局能力。": ". Desktop Bridge ruft nur Whitelist-Objekte auf, die explizit von der Host-Preloading-Schicht bereitgestellt werden, und öffnet nicht die globalen Funktionen von Node.",
  "。66 种行为和 75 种事件形成完整字面量联合类型；": ". 66 Verhaltensweisen und 75 Ereignisse bilden einen vollständigen wörtlichen Vereinigungstyp;",
  "。对话框、抽屉等复合结构使用": ". Wird in Verbundstrukturen wie Dialogfeldern und Schubladen verwendet",
  "。旧字段": ". altes Feld",
  "。默认示例保持白色 Light 和小圆角。": ". Das Standardbeispiel behält das weiße Licht und die kleinen abgerundeten Ecken bei.",
  "。涉及 button、input、select、form、table、nav、aside 等原生语义时，应优先采用属性形式，让键盘、表单提交、浏览器校验和辅助技术继续使用原生行为。": ". Wenn es um native Semantiken wie Schaltfläche, Eingabe, Auswahl, Formular, Tabelle, Navigation, Seite usw. geht, sollte der Verwendung von Attributen Vorrang eingeräumt werden, damit Tastaturen, Formularübermittlungen, Browservalidierung und unterstützende Technologien weiterhin native Verhaltensweisen verwenden können.",
  "。所有对象 Schema 都关闭未知字段或显式声明动态值类型。": ". Alle Objektschemata deaktivieren unbekannte Felder oder deklarieren explizit dynamische Werttypen.",
  "。它还会透传 className、style、ID、ARIA 与其他原生属性；": ". Außerdem werden Klassenname, Stil, ID, ARIA und andere native Attribute transparent übertragen.",
  "。它验证 AngularJS": ". Es validiert AngularJS",
  "。它逐项映射全部 506 个 CSS 组件和 66 种 DOM 行为，同时提供 538 个根运行时导出、21 个 TypeScript 类型导出、29 个包入口与 28 个组件 CSS 包代理。": ". Es ordnet alle 506 CSS-Komponenten und 66 DOM-Verhaltensweisen Element für Element zu und bietet gleichzeitig 538 Root-Laufzeitexporte, 21 TypeScript-Typexporte, 29 Paketeinstiegspunkte und 28 Komponenten-CSS-Paket-Proxys.",
  "。它逐项映射全部 506 个 CSS 组件和 66 种 DOM 行为，同时提供 538 个根运行时导出、22 个 TypeScript 类型导出、 29 个公共包入口与 28 个组件 CSS 包代理。": ". Es ordnet alle 506 CSS-Komponenten und 66 DOM-Verhaltensweisen Element für Element zu und bietet gleichzeitig 538 Root-Laufzeitexporte, 22 TypeScript-Typexporte, 29 öffentliche Paketeinstiegspunkte und 28 Komponenten-CSS-Paket-Proxys.",
  "。未知平台、包或组件会立即失败；输出清单由": ". Unbekannte Plattformen, Pakete oder Komponenten fallen sofort aus; Die Ausgabeliste ist gegeben durch",
  "。稳定资产以": ". Vermögenswerte stabilisieren",
  "。小数点写作下划线，例如": ". Dezimalpunkte werden beispielsweise mit einem Unterstrich geschrieben",
  "。需要自定义前缀、只注册部分组件、关闭": ". Präfix anpassen, nur einige Komponenten registrieren, schließen",
  "。Before 事件可通过": ". Bevor das Ereignis bestanden werden kann",
  "。Home 与示例默认保持白色 Light 和小圆角；深色模式不会被默认启用。": ". Startseite und Muster bleiben standardmäßig weiß mit hellen und kleinen abgerundeten Ecken; Der Dunkelmodus ist standardmäßig nicht aktiviert.",
