  "安全区、动态视口、顶部栏、底部导航、Bottom/Action/Filter Sheet、下拉刷新、无限加载、滑动操作、滚轮选择、键盘避让、移动认证与结算、权限和离线状态都有稳定契约，可直接用于移动网页、PWA 和 Tauri/Electron 移动式 WebView。": "Safe area, dynamic viewport, top bar, bottom navigation, bottom/Action/Filter Sheet, pull-to-refresh, infinite loading, slide operation, wheel selection, keyboard avoidance, mobile authentication and settlement, rights and offline status have stable contracts and can be used direct for mobile web pages, PWA and Tauri/Electron mobile WebView.",
