  "把 506 个 CSS 组件和 66 种 DOM 行为映射为 AngularJS 元素/属性指令，提供模块工厂、严格组件子集、原生 ngModel、十轴主题、3 个可注入服务、动态生命周期与相互隔离的 Tauri / Electron 入口。它面向必须维护 AngularJS 1.8.x 的存量产品，并明确公开框架 EOL 安全边界。": "Karten 506 CSS Komponenten und 66 DOM Verhaltensweisen in AngularJS Element / Attribut Direktiven, Bereitstellung von Modul Fabrik, strenge Komponenten-Subsetting, native ngModel, Zehn-Achsen-Thema, 3 injizierbare Dienste, dynamische Lebenszyklus und isoliert Tauri / Electron Eintrag. Es zielt auf Aktienprodukte ab, die AngularJS 1.8.x beibehalten müssen, und legt die EOL-Sicherheitsgrenzen des Frameworks explizit offen.",
  "把 Web 技术变成完整桌面工作区": "Verwandeln Sie Web-Technologie in einen kompletten Desktop-Arbeitsbereich",
  "白底中性默认": "Neutraler Standard auf weißem Hintergrund",
  "白名单、导出目标与 Publint": "Whitelists, Exportziele und Publint",
  "白色画布、中性色文本、4px 基础圆角、克制阴影。圆角和强层次必须显式选择，不会污染普通业务页面。": "Weiße Leinwand, neutraler Text, 4px grundlegende abgerundete Ecken, zurückhaltender Schatten. Abgerundete Ecken und eine starke Hierarchie müssen explizit ausgewählt werden und belasten keine gewöhnlichen Geschäftsseiten.",
