  "版本线作为只读兼容别名保留；旧": "Versionszeile als schreibgeschützter kompatibler Alias reserviert; alt",
  "帮助": "Hilfe",
  "帮助、状态、语言和登录等辅助入口": "Hilfseingänge wie Hilfe, Status, Sprache und Login",
