  "绑定 Electron 安全桥与销毁周期": "Binding Electron Security Bridge und Zerstörungszyklus",
  "绑定 Tauri 窗口按钮与销毁周期": "Bind Tauri Fenstertaste und Zerstörungszyklus",
  "绑定行为并访问实例": "Bindeverhalten und Zugriffsinstanzen",
  "包裹；容器小于 768px 会独立折叠，不受浏览器窗口宽度干扰。": "Verpackung; Container, die kleiner als 768 Pixel sind, werden unabhängig von der Breite des Browserfensters unabhängig voneinander ausgeblendet.",
  "包含每一项，适合 AI 和构建工具直接读取。": "Enthält jeden Artikel, der zum direkten Lesen durch KI und zum Erstellen von Tools geeignet ist.",
  "包明确支持 Node.js >=18.18、Chrome/Edge/Firefox 100+、Safari/iOS 15.4+ 和 ESM；主入口及桌面适配器提供条件": "Das Paket unterstützt explizit Node.js >=18.18, Chrome/Edge/Firefox 100+, Safari/iOS 15.4+ und ESM; Hauptportal und Desktop-Adapter stellen Bedingungen bereit",
  "包入口": "Paketeintrag",
  "包入口可在服务端安全导入，全部 506 个组件均经过逐项 SSR，行为只在 Effect 生命周期内初始化；服务端标记 Hydration 不产生 recoverable error，并兼容 StrictMode。Tauri 与 Electron 分别使用": "Der Paketeintrag kann serverseitig sicher importiert werden. Alle 506-Komponenten haben die SSR Stück für Stück durchlaufen und das Verhalten wird erst während des Effektlebenszyklus initialisiert; Die serverseitige Markierung Hydration erzeugt keine behebbaren Fehler und ist mit StrictMode kompatibel. Tauri und Electron werden jeweils verwendet",
  "保持兼容，可继续作为业务级壳使用。": "Bleibt kompatibel und kann weiterhin als Business-Shell verwendet werden.",
  "保持为外部 peer dependency，不会把它打进 Gardener 产物，也不会掩盖框架级风险。新项目优先选择 Vue、React 或框架无关入口；存量项目必须同时执行输入净化、CSP、资源白名单、桌面桥最小授权和迁移计划。完整要求见": "Behalten Sie es als externe Peer-Abhängigkeit bei, die es nicht in das Gardener-Produkt überträgt und Risiken auf Framework-Ebene nicht abdeckt. Neue Projekte haben Vorrang, Vue-, React- oder Framework-unabhängige Eingänge zu wählen; Bestehende Projekte müssen außerdem Eingabebereinigung, CSP, Ressourcen-Whitelisting, Desktop-Bridge-Mindestautorisierung und Migrationsplan implementieren. Die vollständigen Anforderungen finden Sie unter",
  "保存": "Speichern",
  "保存草稿": "Entwurf speichern",
  "保存成功": "Erfolgreich gespeichert",
  "保存每次正式构建的 raw、gzip、Brotli、压缩比例及 npm 包体积结果。": "Speichern Sie die Ergebnisse für Roh-, Gzip-, Brotli-, Kompressionsverhältnis und npm-Paketvolumen jedes offiziellen Builds.",
  "保存前可以通过预览检查所有设备宽度。": "Alle Gerätebreiten können vor dem Speichern per Vorschau überprüft werden.",
  "保存筛选、排序和列配置": "Speichern von Filtern, Sortieren und Spaltenkonfigurationen",
