  "保留 Gardener 类、属性、children 与 Ref": "Keep Gardener Klasse, Eigenschaften, Kinder und Ref",
  "保留 Gardener 类、属性与插槽": "Gardener Klasse, Eigenschaften und Slots bewahren",
  "保留空轨位置，适合固定卡槽；min / gap": "Halten Sie die leere Schienenposition, geeignet für die Befestigung des Kartenschlitzes; min / Lücke",
  "报告与发票": "Berichte und Rechnungen",
  "暴露 beforeapproval、beforeclose、beforefilepicker、beforeopen、beforepromptstop、beforepromptsubmit、beforetabclose 7 个必须在 JS/.NET 异步边界前同步阻止的守卫事件。行为成员与事件 detail 契约可从": "Offengelegt vor Approval, BeforeClose, BeforeFilePicker, BeforeOpen, BeforePromptStop, BeforePromptSubmit, BeforeTabClose. 7 Schutzereignisse, die vor asynchronen JS/.NET-Grenzen synchron blockiert werden müssen. Verhaltensmitglieder und Veranstaltungsdetailverträge sind erhältlich unter",
  "暴露全部 75 个事件，": "Alle 75 Ereignisse aufdecken,",
  "本节是给最终用户使用的 AI 产品 UI；后文": "Dieser Abschnitt ist für die AI-Produkt-UI für Endbenutzer; der folgende Text",
