  "表单、导航、浮层、数据、媒体、商业、通信、法律、工作流和 Dashboard 均有稳定结构与状态约定。": "Formulare, Navigation, Overlays, Daten, Medien, Business, Kommunikation, Recht, Workflow und Dashboard haben alle stabile Strukturen und staatliche Konventionen.",
