  "不是缩小桌面，而是完整的移动应用层": "Kein kleinerer Desktop, sondern eine vollständige mobile App-Schicht",
  "不要再为下一张页面重新发明基础设施。": "Hört auf, die Infrastruktur für die nächste Seite neu zu erfinden.",
  "不要在 Renderer 开启 Node Integration，也不要向页面暴露任意 IPC。适配器只接受 minimize、maximize、close、drag 白名单动作。": "Aktivieren Sie keine Node-Integration im Renderer und setzen Sie keinen IPC auf der Seite frei. Der Adapter akzeptiert nur Minimieren, Maximieren, Schließen und Ziehen von Whitelist-Aktionen.",
  "不遮挡内容的补充优先使用 Help Text、Inline Hint 或 Tip；必须绑定控件时使用 Tooltip；包含链接和操作时使用 Help Popover；跨步骤教学使用 Tour。不要把重要错误或必须阅读的法律信息藏进悬浮层。": "Verwenden Sie Hilfetext, Inline-Hinweis oder Tipp für ergänzende Inhalte, die den Inhalt nicht blockieren; Verwenden Sie Tooltip, wenn Steuerelemente gebunden sein müssen; Verwenden Sie Hilfe-Popover, wenn Sie Links und Operationen einbeziehen; Verwenden Sie Tour für den stufenübergreifenden Unterricht. Verstecken Sie keine wichtigen Fehler oder müssen Sie rechtliche Informationen in einer schwimmenden Schicht lesen.",
  "布局": "Layout",
  "布局、表单、导航、数据、内容、账号、商业、移动、桌面和 AI 均可独立引入。": "Layout, Formulare, Navigation, Daten, Inhalte, Konten, Commerce, Mobile, Desktop und AI können alle unabhängig voneinander eingeführt werden.",
  "布局使用逻辑属性，组件覆盖 RTL 下的动画方向与箭头。": "Layout verwendet logische Eigenschaften und Komponenten überschreiben Animationsrichtung und Pfeile unter RTL.",
