  "初始化根节点自身及其后代的全部行为。": "Initialisiert das gesamte Verhalten des Wurzelknotens selbst und seiner Nachkommen.",
  "处理复杂 CustomEvent。值会转换为 .NET 字符串、布尔、数字、数组或字典；DOM、File、BigInt、函数和循环引用会安全序列化。": "Umgang mit komplexen benutzerdefinierten Ereignissen. Werte werden in .NET-Strings, Boolesche Werte, Zahlen, Arrays oder Wörterbücher konvertiert; DOM, File, BigInt, Funktionen und Zirkelverweise werden sicher serialisiert.",
