  "从": "Von",
  "从 52 个成品结构中选择最接近的页面骨架。": "Wählen Sie das nächstgelegene Seitenskelett aus 52 fertigen Strukturen.",
  "从第一次登录，到每一次安全审计": "Vom ersten Login bis zu jedem Security Audit",
  "从第一行 CSS 到几十万套 AI 生成模板，这里描述 Gardener 的稳定接口、选择顺序、环境矩阵和交付边界。": "Von der ersten Zeile von CSS bis hin zu Hunderttausenden von AI-generierten Vorlagen finden Sie hier eine Beschreibung der stabilen Benutzeroberfläche, der Auswahlreihenfolge, der Umgebungsmatrix und der Liefergrenzen von Gardener.",
  "从静态 SSR 到桌面 WebView，使用同一套 Razor 组件": "Vom statischen SSR zum Desktop WebView mit dem gleichen Satz von Razor-Komponenten",
  "从看见商品，到交易与退款完成": "Vom Sehen des Produkts bis zum Abschluss der Transaktion und Rückerstattung",
  "从逻辑 inline-start 方向偏移": "Offset von logischer Inline-Start-Richtung",
  "从企业站主导航到 CMS 树，从移动底栏到 Electron Activity Bar，从右键菜单到 Scrollspy，38 种稳定模式让 AI 直接按意图选择。": "Von der Navigation von Unternehmens-Websitebesitzern bis zum CMS-Baum, von der mobilen unteren Leiste bis zur Electron-Aktivitätsleiste, vom Rechtsklick-Menü bis zum Scrollspy, 38 stabile Modi ermöglichen es der KI, direkt nach Absicht auszuwählen.",
  "从上传一个文件，到完成整套内容生产": "Vom Hochladen einer Datei bis zum Abschluss der gesamten Inhaltsproduktion",
  "从上下主区、左右栏到 Holy Grail、Master / Detail、Dock、可调分栏和全屏工作区，Web、移动端与 Tauri / Electron 直接选用，不必临时编写页面级布局 CSS。": "Von den oberen und unteren Hauptbereichen können linke und rechte Spalten bis hin zu Heiligem Gral, Master / Detail, Dock, einstellbare Spalten und Vollbild-Arbeitsbereich, Web, mobile Terminals und Tauri / Electron direkt ausgewählt werden, ohne dass Sie vorübergehend Seitenlayout-CSS schreiben müssen.",
