  "定义高频页面根类、所有必要部件、适用平台、行为、桌面适配器和用途。它不是截图模板，而是可换主题、可响应、可继续组合的稳定结构。以下展开项保留每个配方的全部字段。": "Definiert die Hochfrequenz-Seitenwurzelklasse, alle notwendigen Komponenten, anwendbare Plattformen, Verhaltensweisen, Desktop-Adapter und Nutzung. Es ist keine Screenshot-Vorlage, sondern eine stabile Struktur, die in Themen umgewandelt werden kann, reagiert und kontinuierlich kombiniert werden kann. Die folgende Erweiterung behält alle Felder für jedes Rezept.",
