  "对比度、包边界、导出和版本": "Kontrast, Paketgrenzen, Export und Version",
  "对话": "Dialog",
  "对话、Composer 与流式回答之外，还需要推理摘要、工具调用和批准、多 Agent 编排、来源引用、Artifact、上下文记忆、Token/费用、语音、权限、隐私、安全复核与反馈评估。Gardener 将整条 AI 任务链做成可直接复用的32种模式。": "Zusätzlich zu Dialog-, Composer- und Streaming-Antworten sind auch eine Zusammenfassung der Argumentation, Tool-Aufruf und -Genehmigung, Multiagenten-Orchestrierung, Quellenzitat, Artefakt, Kontextspeicher, Token / Gebühr, Stimme, Berechtigungen, Datenschutz, Sicherheitsüberprüfung und Feedback-Bewertung erforderlich. Gardener macht die gesamte KI-Aufgabenkette in 32 Modi, die direkt wiederverwendet werden können.",
