  "分栏、命令、菜单、导航、Dock、托盘和 About Dialog": "Spalten, Befehle, Menüs, Navigation, Dock, Taskleiste und Info-Dialog",
  "分栏认证": "Spaltenbescheinigung",
  "分栏认证在 704px 以下收敛为单列；卡片在 384px 以下重排 QR、规则与恢复码；底部操作尊重 Safe Area。": "Spaltenauthentifizierung konvergiert zu einer einzelnen Spalte unter 704px; Karten werden mit QR, Regeln und Wiederherstellungscodes unter 384px neu angeordnet; Bodenoperationen respektieren den Safe Area.",
  "分类": "Klassifikation",
