  "分类进度和占比": "Klassifizierungsfortschritt und Proportion",
  "分片状态、断点续传视觉协议": "Fragmentierungsstatus, Breakpoint Resume Visual Protocol",
  "分析后台": "Analysehintergrund",
  "分享": "Teilen",
  "分组单选、禁用规格、键盘漫游、JSON 输出、": "Gruppierte Funkauswahl, deaktivierte Spezifikationen, Tastatur-Roaming, JSON-Ausgang,",
  "风险": "Risiko",
  "风险项": "Risikoposition",
  "封面、波形/时间线与控制": "Cover, Waveforms/Timeline und Controls",
  "服务过滤器、视图、图标和色板；": "Servicefilter, Ansichten, Symbole und Farbfelder;",
  "服务器错误、请求编号和重试": "Serverfehler, Anfragenummern und Retries",
  "浮层、Dialog、Toast 等稳定堆叠顺序": "Stabile Stapelsequenz von Floating Layer, Dialog, Toast, etc.",
  "浮层支持 top / bottom / start / end 与 start / center / end 对齐，空间不足时自动翻转并限制在视口内；RTL 会交换逻辑方向。": "Die schwimmende Schicht unterstützt die Ausrichtung von oben / unten / Anfang / Ende und Anfang / Mitte / Ende. Wenn nicht genügend Platz vorhanden ist, wird es automatisch umgedreht und auf den Viewport beschränkt; RTL tauscht logische Richtungen aus.",
  "浮动动作按钮": "Floating Action Button",
  "符号": "Symbol",
  "负责人": "Verantwortliche Person",
  "附加配置属性": "Zusätzliche Konfigurationseigenschaften",
  "复用运行时": "Laufzeit wiederverwenden",
  "复用桌面菜单项；在线状态、窗口入口与退出": "Desktop-Menüelemente wiederverwenden; Online-Status, Fenstereingabe und -ausgang",
  "复杂但高复用的页面已经组合为配方。AI 应先选配方，再用组件和工具类做有限调整。": "Komplexe, aber stark wiederverwendbare Seiten wurden zu Rezepten zusammengefasst. KI sollte zuerst Rezepte auswählen und dann begrenzte Anpassungen mithilfe von Komponenten und Werkzeugklassen vornehmen.",
  "复杂非连续布局": "Komplexes nicht zusammenhängendes Layout",
  "复杂任务": "Komplexe Aufgaben",
  "复杂业务配方": "Komplexe Geschäftsrezepte",
  "复制": "Kopie",
  "复制安装命令": "Installationsbefehl kopieren",
  "覆盖": "Überschreiben",
  "覆盖 RTL、容器查询、固定区、Dock、Split View、移动安全区与全屏工作区。既有": "Deckt RTL, Containerabfrage, festen Bereich, Dock, geteilte Ansicht, mobilen sicheren Bereich und Vollbild-Arbeitsbereich ab. Vorhanden",
  "覆盖窗口、工作区、标签、命令、快捷键、文件、托盘、更新、通知和恢复状态。": "Deckt Fenster, Arbeitsbereiche, Registerkarten, Befehle, Verknüpfungen, Dateien, Trays, Updates, Benachrichtigungen und Wiederherstellungsstatus ab.",
  "覆盖单个列": "Überschreiben einer einzelnen Spalte",
  "覆盖对话、Composer、Prompt、Thinking、工具批准、Agent、Artifact、生成、上下文、费用、权限、安全、语音和反馈。": "Umfasst Dialog, Composer, Prompt, Thinking, Tool Approval, Agent, Artefakt, Build, Kontext, Gebühren, Berechtigungen, Sicherheit, Stimme und Feedback.",
  "覆盖规则：": "Override Regeln:",
  "覆盖基础原子、通用组件、高密度后台、移动端、内容商业化、AI 工作区与桌面 WebView。默认足够克制，组合能力足够宽。": "Deckt grundlegende Atome, gemeinsame Komponenten, High-Density-Backend, mobiles Terminal, Content-Kommerzialisierung, AI Workspace und Desktop WebView ab. Der Standard ist ausreichend zurückgehalten und die Kombinationsfähigkeit ist breit genug.",
  "覆盖目录、SKU、购物车、结算、履约、支付、订单、订阅、账单、退款和税费。": "Umfasst Katalog, SKU, Warenkorb, Checkout, Erfüllung, Zahlungen, Bestellungen, Abonnements, Abrechnung, Rückerstattungen und Steuern.",
  "覆盖内在响应、RTL、容器查询、Bento、Masonry、滚动吸附、安全区和打印结构。已有": "Deckt intrinsische Antworten, RTL, Containerabfragen, Bento, Masonry, Scroll-Snapping, sichere Bereiche und Druckstrukturen ab. Schon",
  "覆盖全部根类、业务字段组、动态增删、条件显示、容器响应、RTL 与打印。": "Deckt alle Stammklassen, Geschäftsfeldgruppen, dynamische Ergänzungen und Löschungen, bedingte Anzeige, Containerantwort, RTL und Druck ab.",
  "覆盖全部模式并可直接测试 OTP、密码强度、倒计时、账号/租户选择和身份菜单。": "Deckt alle Modi ab und ermöglicht direktes Testen von OTP, Passwortstärke, Countdown, Konto / Mieterauswahl und Identitätsmenü.",
  "覆盖全局、层级、选择、菜单、页内、流程、移动与桌面导航，并可直接测试键盘和右键交互。": "Deckt globale, hierarchische, Auswahl-, Menü-, Seiten-, Prozess-, Mobil- und Desktop-Navigation ab und kann Tastatur- und Rechtsklick-Interaktionen direkt testen.",
  "覆盖上传、文件浏览、媒体、图片、文档、音视频、四类编辑器、协作、版本和存储。": "Umfasst das Hochladen, das Durchsuchen von Dateien, Medien, Bilder, Dokumente, Audio und Video, vier Arten von Editoren, Zusammenarbeit, Versionen und Speicher.",
  "覆盖所有根类、RTL/移动响应、Tooltip、Popover、FAQ 与两步 Tour。": "Deckt alle Stammklassen, RTL/Mobile Responsive, Tooltip, Popover, FAQ und Two-Step Tour ab.",
  "覆盖所有页头、公共栏、Loading、Empty、Error、403、404、500、Offline、Maintenance、Container Query 和 Back to Top。": "Deckt alle Header, gemeinsame Felder, Laden, Leeren, Fehler, 403, 404, 500, Offline, Wartung, Containerabfrage und Zurück nach oben ab.",
  "概览": "Überblick",
  "高复用复杂结构作为组件或配方存在，不要求 AI 每次临时组合。": "Sehr wiederverwendbare komplexe Strukturen existieren als Komponenten oder Rezepte und erfordern nicht, dass die KI jedes Mal vorübergehend kombiniert wird.",
  "高密度工作区无需重新拼装": "Für Arbeitsbereiche mit hoher Dichte ist keine Wiedermontage erforderlich",
  "高密度数据、表格、过滤器和多栏应用。": "Hochdichte Daten, Tabellen, Filter und mehrspaltige Anwendungen.",
  "高频页面不必重新拼装": "Hochfrequenzseiten müssen nicht neu zusammengesetzt werden",
  "高频页面配方": "Hochfrequenzseitenrezept",
  "格式、范围和字段导出": "Format, Bereich und Feldexport",
