  "根类负责页面级响应与区域关系；表单、数据、认证、商业、移动、桌面和 AI 组件仍从前 15 类填入。": "Die Root-Klasse ist für Antworten auf Seitenebene und Zonenbeziehungen verantwortlich; die Formular-, Daten-, Authentifizierungs-, Geschäfts-, Mobil-, Desktop- und KI-Komponenten sind immer noch in den ersten 15 Klassen vorhanden.",
