  "更多": "Mehr",
  "更新、权限、文件选择、托盘、多窗口、深链、单实例和崩溃恢复都要求业务或宿主返回真实结果；组件只提供可预测的展示、事件、焦点和状态结构。": "Updates, Berechtigungen, Dateiauswahl, Tray, Multi-Fenster, Deep Chaining, Single Instanz und Crash Recovery erfordern alle, dass das Unternehmen oder der Host echte Ergebnisse zurückgibt; Komponenten bieten nur vorhersagbare Präsentation, Ereignisse, Fokus und Zustandsstrukturen.",
