  "接受组件名、AngularJS 指令名或 ESM 导出名，并由 506 项联合类型约束；未知名称会立即抛错。同一 AngularJS 实例、模块名和等价选项重复安装是幂等的，不同组件子集、依赖或初始化选项使用同名模块时会明确报错，防止静默得到半注册模块。": "Akzeptiert einen Komponentennamen, AngularJS-Direktivennamen oder ESM-Exportnamen, der durch 506 Vereinigungstypen eingeschränkt ist; unbekannte Namen werden sofort einen Fehler auslösen. Wiederholte Installationen derselben AngularJS-Instanz, des Modulnamens und äquivalenter Optionen sind idempotent. Wenn verschiedene Komponenten-Untergruppen, Abhängigkeiten oder Initialisierungsoptionen Module mit dem gleichen Namen verwenden, wird ein Fehler explizit gemeldet, um das stillschweigende Erhalten halbregistrierter Module zu verhindern.",
