  "可复用筛选条件": "Wiederverwendbare Filterbedingungen",
  "可关闭组件自动初始化， 方便由页面级运行时统一接管。显式传入的行为 data attribute 优先于生成默认值。": "Die automatische Komponenteninitialisierung kann deaktiviert werden, um eine einheitliche Übernahme durch die Laufzeit auf Seitenebene zu ermöglichen. Das Verhalten der expliziten Übergabe eines Datenattributs hat Vorrang vor der Generierung eines Standardwerts.",
  "可滚动区域应可被键盘聚焦并提供可访问名称；Reduced Motion 会取消原语的平滑滚动。": "Scrollbare Bereiche sollten auf der Tastatur fokussierbar sein und einen zugänglichen Namen liefern; Reduced Motion unterdrückt das reibungslose Scrollen von Primitiven.",
  "可机器验证": "Maschine überprüfbar",
  "可切换公共网站、Dashboard、CRM、行业门户与状态中心预览。": "Schaltbare öffentliche Website, Dashboard, CRM, Industrieportal und Statuscenter Vorschau.",
  "可取消 Before 事件、Approved/Rejected/Cancelled、Reset API": "Vor dem Ereignis stornierbar, Genehmigt/Abgelehnt/Storniert, API zurücksetzen",
  "可取消流程守卫": "Prozessschutz kann abgebrochen werden",
