  "可选索引文本": "Optionaler Indextext",
  "可以跨 32 种页面复用，保证 AI 在换行业时不改变基础语法。": "kann auf 32 Seitentypen wiederverwendet werden, um sicherzustellen, dass sich die grundlegende Syntax von KI bei einem Branchenwechsel nicht ändert.",
  "可用工具类包括": "Zu den verfügbaren Werkzeugklassen gehören:",
  "可用值": "Verfügbare Werte",
  "可直接测试 App Bar、Bottom Navigation、Swipe Tabs、Swipe Actions、Infinite Load、Action/Filter Sheet 与移动选择器。": "Direktes Testen von App Bar, Bottom Navigation, Swipe Tabs, Swipe Actions, Infinite Load, Action / Filter Sheet und mobilen Selektoren.",
  "可直接测试排序、选择、展开、列显隐、搜索、视图切换、移动堆叠表和键盘网格。": "Sortieren, Auswahl, Erweiterung, Spaltensichtbarkeit, Suche, Ansichtsumschaltung, Verschieben gestapelter Tische und Tastaturraster können direkt getestet werden.",
  "可直接测试全选、反选、范围选择、Transfer、Picker、Cascader、Saved Choice 和动态 Builder。": "Select All, Inverse Selection, Range Selection, Transfer, Picker, Cascader, Saved Choice und Dynamic Builder können direkt getestet werden.",
  "可直接供 AI、代码生成器和文档工具读取。全量压缩包实测为 326,076 B raw、50,128 B gzip、26,375 B Brotli；单个": "Direkt lesbar durch KI, Codegeneratoren und Dokumentationstools. Die tatsächliche Größe des vollständig komprimierten Pakets beträgt 326.064 B raw, 50.126 B gzip, 26.381 B Brotli; Single",
  "可直接供 AI、代码生成器和文档工具读取。全量压缩包实测为 404,104 B raw、59,503 B gzip、29,798 B Brotli；单个": "Direkt lesbar durch KI, Codegeneratoren und Dokumentationstools. Die tatsächliche Größe des vollständig komprimierten Pakets beträgt 404.094 B raw, 59.499 B gzip, 29.785 B Brotli; Single",
  "可直接供 AI、代码生成器和文档工具读取。全量压缩包预算为 328,236 B raw、51,605 B gzip、26,932 B Brotli；单个": "Direkt lesbar durch KI, Codegeneratoren und Dokumentationstools. Das Budget für das vollständig komprimierte Paket beträgt 328.220 B raw, 51.602 B gzip, 26.926 B Brotli; Single",
