  "框架提供焦点样式、减少动效、高对比和 Forced Colors 基础，但语义名称与内容顺序仍由页面作者负责。": "Das Framework bietet eine Grundlage für Fokusstile, reduzierte Bewegung, hohen Kontrast und erzwungene Farben, aber semantische Namensgebung und Inhaltsordnung bleiben in der Verantwortung des Seitenautors.",
  "扩展": "Verlängerung",
  "了解发布状态": "Versionsstatus verstehen",
  "类。": "Klasse.",
  "类必须出现在“CSS 全量 API”或“工具类”清单；每个组件、运行时和页面配方还必须出现在各自目录。构建校验会逐文件计算 SHA-256，避免目录落后于源码。": "Die Klasse muss in der CSS-Voll-API- oder Tool-Klassenliste erscheinen; Jede Komponente, Laufzeit und jedes Seitenrezept muss auch in ihren jeweiligen Verzeichnissen erscheinen. Bei der Build-Verifizierung wird SHA-256 dateiweise berechnet, um zu vermeiden, dass Verzeichnisse hinter den Quellcode zurückfallen.",
  "类名": "Klassenbezeichnung",
  "类型，并保留默认语义标签、选择器、状态、部件、行为、平台与无障碍元数据。静态 SSR 阶段直接输出完整 HTML，建立交互连接后才挂载 DOM 行为；参数签名改变会刷新挂载，组件释放时会注销监听器。": "Geben Sie standardmäßige semantische Tags, Selektoren, Zustände, Widgets, Verhaltensweisen, Plattform- und Barrierefreiheitsmetadaten ein und behalten Sie diese bei. Die statische SSR-Phase gibt direkt vollständiges HTML aus und stellt das DOM-Verhalten erst bereit, nachdem eine interaktive Verbindung hergestellt wurde. Änderungen an Parametersignaturen aktualisieren den Mount und der Listener wird abgemeldet, wenn die Komponente freigegeben wird.",
  "类型、所有者、校验值和版权": "Type, Owner, Check Value und Copyright",
  "类型安全监听 gardener:* 事件": "Typsicheres Hören für Gärtner:* Veranstaltungen",
