  "逻辑方向属性": "Attribut logische Richtung",
  "逻辑方向属性覆盖 RTL；Reduced Motion 停止同步脉冲；Forced Colors 为当前 Activity/Tab/Command 提供明确轮廓。": "Logisches Richtungsattribut überschreibt RTL; Reduced Motion stoppt Synchronimpulse; Forced Colors bietet klare Umrisse für aktuelle Aktivität / Tab / Befehl.",
  "逻辑方向属性支持 RTL；Reduced Motion 关闭位移过渡；Forced Colors 强化选中轮廓；打印自动展平外壳。": "Das logische Richtungsattribut unterstützt RTL; „Reduzierte Bewegung“ schaltet Verschiebungsübergänge aus; Erzwungene Farben verstärken ausgewählte Konturen; Beim Drucken werden die Schalen automatisch geglättet.",
  "没有": "Keine",
  "没有结果": "Kein Ergebnis",
  "没有匹配的 {framework} 组件。": "Keine passende {framework}-Komponente.",
  "没有匹配的 CSS 接口。": "Keine übereinstimmende CSS-Schnittstelle.",
  "没有匹配的工具类。": "Keine passende Werkzeugklasse.",
  "没有匹配的组件。": "Keine passende Komponente.",
  "媒体上叠工具、标注、状态；align / justify / margin": "Media Overlay Tools, Anmerkungen, Status; Alignieren / Begründen / Margin",
  "媒体资产工作台与详情栏": "Media Asset Workbench und Detailleiste",
  "每份自定义构建清单还会为可读 CSS、压缩 CSS、Source Map 和随包复制的 Tauri/Electron 适配器生成 SHA-256 与标准 SRI。接收方无需依赖构建机器，即可逐文件验证交付内容是否完整且未被替换。": "Jedes benutzerdefinierte Build-Manifest generiert auch SHA-256 und Standard-SRI für lesbares CSS, komprimiertes CSS, Source Map und den Tauri / Electron-Adapter, der mit dem Paket kopiert wurde. Der Empfänger kann dateiweise überprüfen, ob die Lieferung vollständig ist und nicht ersetzt wurde, ohne sich auf die Baumaschine zu verlassen.",
  "每个 CSS 组件都有对应的": "Jede CSS-Komponente verfügt über eine entsprechende",
  "每个公共组件都能解析到完整所属包，并明确列出连带包含项。": "Jede öffentliche Komponente löst sich zum Gesamtpaket auf, zu dem sie gehört, mit expliziten Einschlüssen.",
  "每个目录同时生成可读 CSS、正式": "Gleichzeitige Generierung von lesbarem CSS pro Verzeichnis, formal",
  "每个组件都以": "Jede Komponente beginnt mit",
  "每项列出声明式初始化属性，以及": "Jedes Element listet deklarative Initialisierungseigenschaften auf und",
  "每项完整列出": "Listen Sie jeden Artikel vollständig auf",
  "每一个": "jeweils",
  "每一个方向，都有现成导航": "Es gibt bereit Navigation in alle Richtungen",
