  "模板生成趋势": "Trends bei der Vorlagenerzeugung",
  "模板写法": "Methode zum Schreiben von Vorlagen",
  "模板写作 g-gardener，动态声明、切换并销毁任意行为": "Vorlage schreiben g-Gärtner, dynamisch erklären, schalten und zerstören willkürliche Verhaltensweisen",
  "模块工厂 · ngModel · 完整类型": "Modul Fabrik · ngModel · Vollständiger Typ",
