  "模型选择、Thinking/Tool、命令菜单、Artifact 标签、文件树": "Modellauswahl, Thinking/Tool, Befehlsmenü, Artefakt-Tag, Dateibaum",
  "默认": "Ausfall",
  "默认 125 个真实浏览器用例": "Standardmäßig 125 echte Browser-Anwendungsfälle",
  "默认、info、success、warning、danger；紧凑技巧": "Standard, Informationen, Erfolg, Warnung, Gefahr; kompakte Fähigkeiten",
  "默认白色 Surface 与 4px 小圆角；组件只使用主题 Token，可在 42 套主色和所有正交主题轴中复用。": "Standardmäßige weiße Oberfläche mit 4px kleinen abgerundeten Ecken; die Komponente verwendet nur Theme-Token, die in 42 Hauptfarbensätzen und allen orthogonalen Themenachsen wiederverwendet werden können.",
  "默认白色 Surface、1px 边框和 4px 小圆角；阴影仅用于命令面板、窗口切换器和菜单等真实浮层。": "Standardmäßige weiße Oberfläche, 1px Rahmen und 4px kleine abgerundete Ecken; Schatten werden nur für echte Overlays wie Kommandofelder, Fensterschalter und Menüs verwendet.",
  "默认白色 Surface、1px 边框与 4px 小圆角；大圆角和强阴影不是移动端默认。": "Standard weiße Oberfläche, 1px Rahmen und 4px kleine abgerundete Ecken; große abgerundete Ecken und starke Schatten sind nicht die Standardeinstellung für Mobilgeräte.",
  "默认导入。Gardener 包本身不会读取全局 AngularJS，根入口可安全用于 SSR 工具链分析。": "Standardmäßig importiert. Das Gardener-Paket selbst liest kein globales AngularJS und der Root-Eintrag ist sicher für die SSR-Toolchain-Analyse.",
  "默认风格适合个人、企业、后台和内容站，不预设强烈品牌人格。": "Der Standardstil ist für Einzelpersonen, Unternehmen, Backends und Content-Stationen geeignet und gibt keine starke Markenpersönlichkeit vor.",
  "默认视觉：": "Default visual:",
  "默认小圆角，可显式扩展": "Standardmäßig kleine abgerundete Ecken, können explizit erweitert werden",
  "默认与整行": "Standard vs. gesamte Zeile",
  "默认执行 125 个真实浏览器用例和 24 个 HTML 结构用例；完整配置覆盖桌面三引擎、Android / iPhone 设备画像和 WCAG 自动检查。": "Führt standardmäßig 125 echte Browser-Anwendungsfälle und 24 HTML-Struktur-Anwendungsfälle aus; die vollständige Konfiguration umfasst Desktop-Drei-Engines, Android / iPhone-Geräteporträts und WCAG-Automatikprüfungen.",
