  "实时组合示例": "Echtzeit-Kombinationsbeispiel",
  "实现 CSS 或 Runtime。": "Implementieren Sie CSS oder Runtime.",
  "使用": "Verwendung",
  "使用 {theme} 主题": "Theme {theme} verwenden",
  "使用 704px 容器折叠；文件浏览、媒体详情、图片编辑器、文档缩略图、Markdown 双栏和版本对比均有移动布局。": "704px-Container-Reduzierung verwenden; Dateibrowser, Mediendetails, Bildeditor, Miniaturansichten von Dokumenten, Markdown-Doppelspalten und Versionsvergleich verfügen alle über mobile Layouts.",
  "使用 Ajv 2020-12 执行 48 个标准验证用例，覆盖十份发布/配置文档、未知根字段、十类未知嵌套字段、十类缺失嵌套必填字段、跨 Schema 引用、JavaScript 标识符、SHA-256 格式、基线回归状态和旧组件 Schema 兼容别名；": "48 Standardvalidierungsanwendungsfälle mit Ajv 2020-12 ausgeführt, die zehn Release-/Konfigurationsdokumente, unbekannte Stammfelder, zehn Arten unbekannter verschachtelter Felder, zehn Arten fehlender verschachtelter Pflichtfelder, schemaübergreifende Referenzen, JavaScript-Identifikatoren, SHA-256-Formate, Baseline-Regressionsstatus und mit Legacy-Komponentenschemas kompatible Aliase abdecken;",
  "使用 gzip level 9 与 Brotli quality 11，对全部 42 个正式压缩产物同时计算 raw、gzip 和 Brotli，并检查全量 CSS、Runtime 的压缩比例，以及": "Berechnen Sie mit gzip Level 9 und Brotli-Qualität 11 gleichzeitig Raw, gzip und Brotli für alle 42 offiziellen Komprimierungsprodukte und überprüfen Sie das Komprimierungsverhältnis von vollständigem CSS, Runtime und",
  "使用 Node.js 内置测试运行器和 Happy DOM，对公共清单中的全部 66 种行为逐项双向比对真实实例成员，并验证初始化、幂等性、销毁和重新初始化；同时覆盖 MutationObserver 的动态节点、动态属性、子树移除、作用域销毁、多行为共存、全局销毁和初始化事件冒泡。": "Verwenden Sie Node.js eingebauten Testläufer und Happy DOM bidirektional reale Instanzmitglieder für alle 66 Verhaltensweisen in der öffentlichen Liste zu vergleichen und zu verifizieren Initialisierung, Idempotenz, Zerstörung und Reinitialisierung; während MutationObserver dynamische Knoten, dynamische Attribute, Unterbaumentfernung, Umfang Zerstörung, Multi-Verhalten Koexistenz, globale Zerstörung und Initialisierung Ereignis sprudeln.",
  "使用 TypeScript 严格模式编译真实消费者，覆盖默认及命名导出、行为工厂、Toast、实例查询和两类桌面桥接。": "Kompilieren Sie echte Verbraucher im strikten TypeScript-Modus, der Standard- und benannte Exporte, Verhaltensfabriken, Toasts, Instanzabfragen und zwei Arten von Desktop-Brücken abdeckt.",
