  "视口响应 · 容器响应 · 逻辑方向 · 打印展平 · 桌面工作台": "Viewport Responsiveness · Container Responsiveness · Logical Direction · Print Flattening · Desktop Workbench",
  "视口小于 768px 时，多栏、Master / Detail 和检查器布局按语义顺序纵向排列；Dock 默认只保留主区，可用": "Wenn das Ansichtsfenster kleiner als 768 Pixel ist, werden mehrspaltige, Master-/Detail- und Inspektor-Layouts vertikal in semantischer Reihenfolge angeordnet; Das Dock behält standardmäßig nur den Hauptbereich und ist verfügbar",
