  "视图": "Ansicht",
  "试用": "Versuch",
  "是 Gardener CSS 1.0.0 的官方 AngularJS 1.x 遗留系统适配层，当前版本为": "ist die offizielle AngularJS 1.x Legacy-Systemanpassungsschicht für Gardener CSS 1.0.0, die aktuelle Version ist",
  "是 Gardener CSS 1.0.0 的官方 Razor Class Library，当前版本为": "ist die offizielle Razor Class Library für Gardener CSS 1.0.0, die aktuelle Version ist",
  "是 Gardener CSS 1.0.0 的官方 React 适配层，当前版本为": "ist die offizielle React-Adaptionsschicht von Gardener CSS 1.0.0, die aktuelle Version ist",
  "是 Gardener CSS 1.0.0 的官方 Vue 3 适配层，当前版本为": "ist die offizielle Vue 3-Adaptionsschicht von Gardener CSS 1.0.0, die aktuelle Version ist",
  "是给生成器使用 Gardener 的约束。前者提供界面组件，后者规定选能力、配方、组件和工具类的顺序。": "ist eine Einschränkung für die Verwendung von Gardener auf Generatoren. Ersteres stellt Schnittstellenkomponenten bereit, und letzteres gibt die Reihenfolge an, in der Fähigkeiten, Rezepte, Komponenten und Werkzeugklassen ausgewählt werden.",
  "是公共命名与程序接口的规范清单，完整登记 CSS 层、包入口、主题属性、JavaScript 导出、行为、事件、桌面适配器和兼容字段。": "ist eine kanonische Liste öffentlicher Benennungs- und Programmierschnittstellen, die CSS-Ebenen, Paketeinträge, Designeigenschaften, JavaScript-Exporte, Verhalten, Ereignisse, Desktop-Adapter und Kompatibilitätsfelder vollständig registriert.",
  "是五个公共区域；": "sind fünf Gemeinschaftsbereiche;",
  "是预压缩单文件入口。SSR 导入不访问浏览器全局对象，行为只在组件挂载后初始化，因此可用于服务端渲染与 Hydration。": "ist ein vorkomprimierter Einzeldateieintrag. Der SSR-Import greift nicht auf globale Browserobjekte zu und das Verhalten wird erst initialisiert, nachdem die Komponente gemountet wurde, sodass es für serverseitiges Rendering und Hydration verwendet werden kann.",
  "适合 WebView": "Geeignet für WebView",
