  "释放监听器、计时器和实例引用。": "Veröffentlichen Sie Listener, Timer und Instanzreferenzen.",
  "收藏": "Sammlung",
  "收录完整 42 个颜色主题，默认保持白底 Light 与小圆角 small。 5 个作用域服务为": "Enthält 42 Farbthemen, mit dem standardmäßigen weißen Hintergrund Hell und den kleinen abgerundeten Ecken klein. Die 5 Umfangsdienste sind",
