  "手势提示": "Gestenaufforderung",
  "手势只增强效率：Pull Refresh 有刷新按钮路径，Infinite Load 有“加载更多”，Swipe Actions 有 Toggle，Wheel Picker 支持键盘。": "Gesten erhöhen nur die Effizienz: Pull Refresh hat einen Refresh-Tastenpfad, Infinite Load hat \"mehr laden\", Swipe Actions hat Toggle und Wheel Picker hat Tastaturunterstützung.",
