  "输出前校验端点、键盘、焦点、状态、RTL、打印和高对比环境。": "Endpunkte, Tastatur, Fokus, Status, RTL, Druck und kontrastreiche Umgebungen vor der Ausgabe überprüfen.",
  "输入发送到 +86 138****6608 的验证码": "Geben Sie den Bestätigungscode an +86 138****6608 ein",
  "输入类名、完整选择器、CSS 属性、值或响应条件。为避免一次渲染 11,498 项，至少输入两个字符后分批显示，每次 100 项；输入": "Geben Sie einen Klassennamen, einen vollständigen Selektor, eine CSS-Eigenschaft, einen Wert oder eine Antwortbedingung ein. Um zu vermeiden, dass 11.498 Elemente auf einmal gerendert werden, geben Sie mindestens zwei Zeichen ein, bevor die Anzeige in Stapeln von jeweils 100 Elementen erfolgt. eintreten",
  "输入命令": "Befehl eingeben",
  "输入命令或文件名": "Befehls- oder Dateiname eingeben",
