  "属性、样式、审计、上下文信息": "Eigenschaften, Stile, Auditing, Kontextinformationen",
  "属性的真实源码命中，将 506 个组件解析到一个或多个完整所属包，而不是截取单个选择器，因此伪类、状态、动画、子部件、容器查询和依赖规则不会丢失。": "Echte Quellcode-Treffer für Eigenschaften, die 506 Komponenten in ein oder mehrere vollständige zugehörige Pakete auflösen, anstatt einzelne Selektoren abzuschneiden, sodass Pseudoklassen, Zustände, Animationen, Unterteile, Containerabfragen und Abhängigkeitsregeln nicht verloren gehen.",
