  "搜索组件": "Suchkomponente",
  "缩进层级、父子行展开": "Indent-Level, Erweiterung der Eltern-Kind-Linie",
  "缩略图、名称、属性和快捷动作": "Thumbnails, Namen, Eigenschaften und schnelle Aktionen",
  "缩略图网格与媒体多选": "Thumbnail-Raster und Medien Multiple Selektion",
  "所有 32 模式均进入组件 Manifest 和动态组件目录；CSS 源码完整 API 也会列出模块、选择器、变量和状态。": "Alle 32 Modi gehen in Komponentenmanifeste und dynamische Komponentenverzeichnisse; CSS-Quell-Voll-API listet auch Module, Selektoren, Variablen und Status auf.",
  "所有结构采用逻辑方向属性并支持 RTL；Forced Colors 提供选择轮廓；打印隐藏数据操作，展开详情和层级行，并移除滚动裁切。": "Alle Strukturen übernehmen logische Richtungsattribute und unterstützen RTL; Forced Colors bietet Auswahlumrisse; Drucken von versteckten Datenoperationen, Erweitern von Detail- und Hierarchiezeilen und Entfernen von Scroll-Clips.",
  "所有开始、结束和操作对齐使用逻辑方向；Floating Action Bar、Back to Top 同时读取设备安全区。": "Alle Start-, End- und Aktionsausrichtungen verwenden die logische Richtung; Floating Action Bar, Zurück nach oben liest auch den sicheren Bereich des Geräts.",
  "所有模式覆盖键盘、RTL、Reduced Motion、Forced Colors 与打印；移动结算尊重 Safe Area，打印隐藏购买动作并保留订单、发票和税费信息。": "Alle Modi umfassen Tastatur, RTL, Reduzierte Bewegung, Erzwungene Farben und Druck; Mobile Abrechnung respektiert Safe Area, Druck versteckt Kaufaktionen und behält Bestellung, Rechnung und Steuerinformationen.",
  "所有模式使用白色 Surface、1px 边框和4px小圆角；在 960/704/512px 容器宽度下折叠 Artifact、Sidebar 与双列模式，并覆盖 RTL、Forced Colors 和打印。": "Verwenden Sie weiße Oberfläche, 1px Rahmen und 4px kleine abgerundete Ecken in allen Modi; Zusammenbruch Artefakt, Sidebar und Dual Column Modi bei 960/704/512px Containerbreite und überschreiben RTL, erzwungene Farben und Druck.",
  "所有模式使用逻辑方向并覆盖 RTL、Reduced Motion、Forced Colors 和打印；打印隐藏上传与编辑动作，展平滚动区并保留正文和修订信息。": "Alle Modi verwenden die logische Richtung und decken RTL, Reduced Motion, Forced Colors und Print ab; Print verbirgt das Hochladen und Bearbeiten von Aktionen, verflacht den Scrollbereich und bewahrt Text- und Revisionsinformationen.",
  "所有水平语义使用 inline/start/end；Media Object、Bleed、Imposter、Overlay、Reel 和 Scroll Snap 支持 RTL。": "Alle horizontalen Semantiken verwenden inline/start/end; Media Object, Bleed, Imposter, Overlay, Reel und Scroll Snap unterstützen RTL.",
  "所有图片有符合目的的": "Alle Bilder erfüllen ihren Zweck",
  "所有样式覆盖 RTL、Reduced Motion、Forced Colors 与打印。打印隐藏密码、Provider、倒计时和敏感操作，只保留必要的安全审计信息。": "Alle Stile umfassen RTL, Reduced Motion, Forced Colors und Druck. Drucken Sie versteckte Passwörter, Anbieter, Countdowns und sensible Vorgänge, wobei Sie nur die erforderlichen Sicherheitsüberprüfungsinformationen beibehalten.",
  "所有原生 attributes、DOM 事件和 slots 均透传。组件模板 Ref 统一公开": "Alle nativen Attribute, DOM-Ereignisse und Slots werden durchgereicht. Komponentenvorlage Verweis auf einheitliche Offenlegung",
  "所有组合使用逻辑方向属性；Input Group、Money、Unit、字段动作和 Sticky Actions 在 RTL 下保持正确首尾关系。": "Alle Kombinationen verwenden logische Richtungsattribute; Input Group, Money, Unit, Field Actions und Sticky Actions pflegen unter RTL die korrekte Kopf-an-Zahl-Beziehung.",
  "锁屏": "Sperrbildschirm",
  "套餐、版本和能力横向比较": "Horizontaler Vergleich von Paketen, Versionen und Fähigkeiten",
  "提供 640px 容器折叠；移动端 Picker Panel 自动成为底部面板，Batch Toolbar 避让安全区。": "Bietet einen Containereinbruch von 640px; das mobile Picker Panel wird automatisch zum unteren Panel und die Batch-Symbolleiste vermeidet den sicheren Bereich.",
  "提供 Unicode 搜索、网格/列表切换、单项选择、方向键、Home、End、Enter 和 Space，并发布选择事件。": "Bietet Unicode-Suche, Raster-/Listenwechsel, Einzelauswahl, Pfeiltasten, Pos1, Ende, Eingabetaste und Leertaste und veröffentlicht Auswahlereignisse.",
  "提供传统 12 栅格。两者都使用原生 CSS Grid、逻辑方向和统一断点，不依赖负边距。": "Bietet traditionelles 12-Raster. Beide verwenden natives CSS-Raster, logische Richtung und einheitliche Haltepunkte und verlassen sich nicht auf negative Ränder.",
  "提供每个页面的端、部件、运行时和用途；": "Bietet das Terminal, Widgets, Laufzeit und Zweck jeder Seite;",
  "提供适合编辑器、AI 工具和超级 CMS 的固定视口布局。通过": "Bietet ein festes Ansichtsfenster-Layout, das für Redakteure, KI-Tools und Super-CMS geeignet ist. Pass",
  "提供稳定初始高度，": "Sorgt für eine stabile Anfangshöhe,",
