  "通用组件 + mobile / mobile-compositions": "Universalkomponenten + mobile / mobile Zusammensetzungen",
  "通用组件，排除移动/桌面专属组合": "Generische Komponenten, ausgenommen mobile/desktopspezifische Kombinationen",
  "同步中": "Synchronisieren",
  "同时检查 PC、移动网页与桌面 WebView。": "Überprüfen Sie gleichzeitig PC, mobiles Web und Desktop WebView.",
  "同时提供五档响应式版本": "Auch in der reaktionsschnellen Fünfgangversion verfügbar",
  "同时支持元素和属性形式，例如": "Unterstützt sowohl Element- als auch Attributformulare, z. B.",
  "同一套 CSS，也有完整的 React 组件模型": "Derselbe CSS-Satz hat auch ein komplettes React-Komponentenmodell",
  "同一套语言，覆盖所有端": "Die gleiche Sprache deckt alle Terminals ab",
  "同一整页契约可切换企业、个人、医疗、金融或公共服务主题。": "Derselbe ganzseitige Vertrag kann geschäftliche, persönliche, medizinische, finanzielle oder öffentlich-rechtliche Themen wechseln.",
  "统一": "Vereinigung",
  "统一垂直节奏；default、bordered": "Einheitlicher vertikaler Rhythmus; Standard, begrenzt",
  "统一单选/多选、Unicode 搜索、Chip 删除、隐藏字段输出、方向键、Home、End、Enter、Space、Escape 和点击外部关闭。": "Unified single/multiple selection, Unicode search, Chip delete, hidden field output, arrow keys, Home, End, Enter, Space, Escape und click outside to close.",
  "统一的": "vereinheitlicht",
  "统一工具命令、Ctrl/Command 快捷键、字符与词数；富文本、Markdown、代码和区块编辑器共用协议。": "Vereinheitlichen von Tool-Befehlen, Strg/Befehl-Verknüpfungen, Zeichen- und Wortzählungen; gemeinsame Protokolle für Rich Text, Markdown, Code- und Block-Editoren.",
  "统一命名": "Einheitliche Benennung",
