  "先建立租户与身份边界，再组织内容工作流、Dashboard 和门户页面。": "Legen Sie Mandanten- und Identitätsgrenzen fest, bevor Sie Inhaltsworkflows, Dashboards und Portalseiten organisieren.",
  "先判断导航范围（全局、局部、层级或页内），再判断方向和终端；Tabs 只切换同一上下文内的视图，Breadcrumb 只表达位置，Pagination 只表达结果集翻页，不应互相替代。": "Bestimmen Sie zuerst den Navigationsumfang (global, lokal, hierarchisch oder intra-page) und dann die Richtung und das Terminal; Tabs wechselt nur Ansichten im selben Kontext, Breadcrumb drückt nur Position aus und Pagination drückt nur Ergebnis-Set-Seitenwechsel aus und sollte sich nicht gegenseitig ersetzen.",
  "先判断数据形态，再判断操作强度。少量静态属性用 Description List 或 Key Value；多记录用 List 或 Table；单元格需要键盘移动和编辑时才使用 Data Grid；层级数据使用 Tree 或 Tree Table；趋势和比较先提供可读数值，再增加图形。": "Bestimmen Sie zuerst das Datenformular und dann die Operationsintensität. Verwenden Sie Beschreibungsliste oder Schlüsselwert für eine kleine Anzahl von statischen Attributen; Verwenden Sie Liste oder Tabelle für mehrere Datensätze; Verwenden Sie Data Grid nur, wenn Zellen Tastaturbewegung und -bearbeitung erfordern; Verwenden Sie Baum oder Baumtabelle für hierarchische Daten; Trends und Vergleiche liefern zuerst lesbare Werte und fügen dann Grafiken hinzu.",
