  "颜色主题与中性色、字体、形状、密度、层次、动效、平台和操作系统正交组合。这里始终保持白色浅色界面，只切换品牌主色。": "Farbthemen werden orthogonal mit Neutralen, Schriftarten, Formen, Dichten, Ebenen, Animationen, Plattformen und Betriebssystemen kombiniert. Die Weiß- und Lichtschnittstelle wird hier immer beibehalten und nur die Hauptmarkenfarbe wird gewechselt.",
  "颜色主题只负责品牌主色；显示模式与其他主题轴相互独立。本站固定使用 Light，以保持白色文档体验，但框架同时提供 Dark、System 与 High Contrast。": "Das Farbthema ist nur für die Hauptfarbe der Marke verantwortlich; Der Anzeigemodus ist unabhängig von anderen Themenachsen. Diese Website verwendet Light, um ein weißes Dokumenterlebnis zu gewährleisten, aber das Framework bietet auch Dark, System und High Contrast.",
