  "页面不存在": "Seite existiert nicht",
  "页面不能只实现正常数据态。至少要明确 Loading、Empty、Error；面向路由和完整应用时还应准备 403、404、500、Offline 和 Maintenance。Gardener 为这些状态提供相同的内容、视觉、详情、操作和帮助部件。": "Die Seite kann nicht nur den normalen Datenzustand implementieren. Zumindest Laden, Leeren und Fehler sollten klar sein; für das Routing und vollständige Anwendungen sollten auch 403, 404, 500, Offline und Wartung vorbereitet werden. Gardener bietet die gleichen Inhalte, Visuals, Details, Aktionen und Hilfe-Widgets für diese Zustände.",
