  "页面管理": "Seitenmanagement",
  "页面级 Header、指标、主内容、辅助区和移动折叠已有稳定契约。": "Seitenebenen-Header, Indikatoren, Hauptinhalte, Hilfsbereiche und mobile Ordner haben stabile Verträge.",
