  "页面结构、主题 Token 与交互语义保持一致，各端只增加必要的密度、窗口和安全区适配。": "Die Seitenstruktur, Theme-Token und Interaktionssemantik sind konsistent, und nur notwendige Dichte-, Fenster- und Safe-Zone-Adaptionen werden an jedem Ende hinzugefügt.",
