  "页面状态的 visual、code、title、description、details、actions、help 部件可以按需要省略，但标题和可恢复入口不应同时缺失。": "Visual, Code, Titel, Beschreibung, Details, Aktionen und Hilfekomponenten des Seitenstatus können bei Bedarf weggelassen werden, aber der Titel und der wiederherstellbare Eintrag sollten nicht gleichzeitig fehlen.",
