  "营销、个人和内容页使用自然文档滚动；Dashboard 与工作台允许高密度多栏；医疗、金融和政务只是 UI 契约，不替代法规、身份验证、隐私、审计和后端业务规则。": "Marketing-, Personal- und Content-Seiten verwenden natürliches Dokumentenscrollen; Dashboard und Workbench ermöglichen mehrere Spalten mit hoher Dichte; Gesundheitswesen, Finanzen und Regierung sind nur UI-Verträge und ersetzen keine Vorschriften, Authentifizierung, Datenschutz, Auditierung und Backend-Geschäftsregeln.",
