  "用于真实验证 24 / 12、RTL、Container Query 与打印结构。构建检查会逐项验证所有类，而不是只检查几个示例。": "Für echte Verifizierung rund um die Uhr, RTL, Containerabfrage und Druckstruktur. Build-Checks überprüfen alle Klassen einzeln, anstatt nur einige Beispiele zu überprüfen.",
  "用于直接读取上下文。默认仍是白色 Light 与小圆角，不会自动启用深色主题。": "zum direkten Lesen des Kontexts. Die Standardeinstellung ist immer noch weißes Licht mit kleinen abgerundeten Ecken, und das dunkle Design wird nicht automatisch aktiviert.",
