  "与 AI 页面生成协议的区别：": "Unterschiede zum AI Page Generation Protocol:",
  "与 Node.js": "mit Node.js",
  "与安全 preload，只暴露 Minimize、Maximize/Restore、Close 等白名单方法；不要开启 Node Integration，也不要把任意 IPC 通道暴露给页面。": "Stellen Sie beim Sicherheits-Preload nur Whitelist-Methoden wie „Minimieren“, „Maximieren/Wiederherstellen“ und „Schließen“ zur Verfügung. Aktivieren Sie die Knotenintegration nicht und stellen Sie der Seite keine IPC-Kanäle zur Verfügung.",
  "与当前页面或表单上下文绑定的帮助": "Hilfe gebunden an die aktuelle Seite oder Form Kontext",
