  "原生 attributes、事件、children 与": "Native Attribute, Ereignisse, Kinder und",
  "原生 input 后备；发出": "Nativer Eingabe-Fallback; emittiert",
  "原生 input、textarea 和 select 的模型语义仍由 AngularJS 自己管理，适配层不会覆盖": "Die Modellsemantik von nativer Eingabe, Textbereich und Auswahl wird weiterhin von AngularJS selbst verwaltet und wird nicht von der Anpassungsschicht abgedeckt.",
  "原生 input/change 自动去重": "Automatische Deduplizierung von nativen Eingaben/Änderungen",
  "原生标题栏、窗口按钮、菜单和活动栏只是起点；文档标签、可调分栏、Dock、检查器、命令面板、文件选择、托盘、多窗口、后台任务、更新、权限与崩溃恢复均已有稳定组合，可直接落地 Tauri 与 Electron。": "Native Titelleisten, Fenstertasten, Menüs und Aktivitätsleisten sind nur der Ausgangspunkt; Dokumentbeschriftungen, einstellbare Spalten, Dock, Inspektor, Befehlsfeld, Dateiauswahl, Tray, Multi-Fenster, Hintergrundaufgaben, Updates, Berechtigungen und Crash Recovery wurden alle stabil kombiniert und können direkt in Tauri und Electron implementiert werden.",
  "原生表单和自定义 Gardener 事件均支持": "Sowohl native Form als auch benutzerdefinierte Gardener-Events werden unterstützt",
  "原生权限请求、网络状态、数据加载、支付、认证和媒体缩放由业务或宿主实现；Gardener 提供稳定视觉、状态、事件与无障碍接口，不伪造结果。": "Native Berechtigungsanforderungen, Netzwerkstatus, Datenladen, Zahlung, Authentifizierung und Medienskalierung werden vom Unternehmen oder dem Host implementiert; Gardener bietet stabile Vision, Status, Ereignisse und zugängliche Schnittstellen, ohne Ergebnisse zu fälschen.",
  "原始 JSON 清单": "Raw JSON Manifest",
  "原始选择器": "Originalselektor",
