  "阅读宽度、水平或内容居中；max / gutter": "Lesebreite, Ebene oder Inhaltszentrum; max / Gutter",
  "阅读文档": "Dokumentation lesen",
  "允许后续 1.x 新增，禁止无迁移路径的删除；在 1.0.0 稳定切点还会反向检查已有入口是否漏记。废弃入口至少保留两个次版本，并只能在新的主版本移除。其闭合结构由": "Nachfolgende 1.x-Hinzufügungen zulassen und Löschungen ohne Migrationspfade verbieten; Beim stabilen Grenzwert 1.0.0 werden vorhandene Einträge auch umgekehrt überprüft, um festzustellen, ob sie fehlen. Veraltete Einträge bleiben in mindestens zwei Nebenversionen bestehen und können nur in einer neuen Hauptversion entfernt werden. Seine geschlossene Struktur besteht aus",
  "允许写入页面模板？": "Erlauben Sie das Schreiben in die Seitenvorlage?",
  "允许一次": "Einmal erlaubt",
  "运行环境": "Betriebsumgebung",
  "运行时": "Laufzeit",
  "运行时，根据滚动位置显示，点击后平滑返回顶部；Reduced Motion 环境自动使用即时滚动。": "Zur Laufzeit basiert die Anzeige auf der Scroll-Position und kehrt nach dem Klicken reibungslos nach oben zurück; Die Reduced Motion-Umgebung verwendet automatisch sofortiges Scrollen.",
  "运行时、可访问性与环境规则": "Laufzeit, Zugänglichkeit und Umgebungsregeln",
  "运行时测试门禁（0.4.0 起）": "Testen Sie die Zugriffskontrolle zur Laufzeit (seit 0,4.0)",
  "运行时框架无关，通过": "Laufzeit-Framework unabhängig, bestanden",
  "运行时事件": "Laufzeitereignisse",
  "运行时维护状态": "Laufzeitwartungsstatus",
  "运行时行为新增或改名时，公共 API、示例/补充夹具和逐行为测试必须同步，否则测试会因缺少夹具、实例或成员而失败。": "Wenn ein Laufzeitverhalten hinzugefügt oder umbenannt wird, müssen die öffentliche API, die Muster-/Ergänzungs- und die Verhaltenstests synchronisiert werden, da die Tests sonst aufgrund fehlender Geräte, Instanzen oder Mitglieder fehlschlagen.",
  "运行时与环境规则": "Laufzeit- und Umweltregeln",
  "运行中": "laufen",
  "在 200% 缩放、RTL、Reduced Motion、Forced Colors 下仍可操作。": "Noch funktionsfähig bei 200% Skalierung, RTL, Reduced Motion, Forced Colors.",
  "在 704px 折叠详情/结算双栏，在 480px 重排行项目与选择卡；视口查询作为没有容器上下文时的兜底。": "Doppelte Spalten für Details/Bezahlvorgang bei 704 Pixel reduzieren, Werbebuchungen neu anordnen und Karten bei 480 Pixel auswählen; Ansichtsfensterabfrage als Fallback, wenn kein Containerkontext vorhanden ist.",
  "在视口或": "Im Ansichtsfenster bzw",
  "在整个": "Durchgehend",
  "增加可运行示例与验证输入。": "Füge lauffähige Beispiele und Validierungseingang hinzu.",
  "增加数量": "Erhöhung der Menge",
  "栅格": "Gitter",
  "粘性辅助栏": "Hilfsstab klebrig",
  "粘性购买栏": "Sticky Buy Bar",
  "展开": "Erweitern",
  "展开任一模块可查看该文件公开的类、Token、状态、数据属性和关键帧。生成型工具模块链接到独立的 11,498 项清单。": "Erweitern Sie ein beliebiges Modul, um die Klassen, Token, Zustände, Datenattribute und Keyframes anzuzeigen, die von der Datei angezeigt werden. Das Modul generative tools verbindet sich mit einem separaten 11.498-Artikelinventar.",
  "展开详情": "Details erweitern",
