  "长表单、编辑任务、焦点管理与动态视口": "Lange Formulare, Bearbeitungsaufgaben, Fokusmanagement und dynamische Viewports",
  "长流程步骤目录与内容区": "Langer Prozessschritt Verzeichnis und Inhaltsbereich",
