  "账号": "Konto",
  "账号、租户与身份是不同概念，分别使用 Chooser/Switcher，避免在多组织 CMS 中误操作。": "Konto, Mieter und Identität sind unterschiedliche Konzepte. Verwenden Sie Selecter/Switcher, um Fehloperationen im CMS mit mehreren Organisationen zu vermeiden.",
  "账号安全中心": "Account Security Center",
  "账号体系": "Kontosystem",
  "账号选择": "Kontoauswahl",
