  "字段、分区、水平与行内布局、搜索/密码/计数、选择组、验证、姓名/地址/金额、条件与可重复项、审核和提交动作都已组合好。AI 只需选择业务意图，不必反复组织表单 CSS。": "Felder, Partitionen, Horizontales und Inline-Layout, Suche / Passwort / Zähler, Gruppen auswählen, Validierung, Name / Adresse / Menge, Bedingungen und Wiederholbarkeiten, Überprüfung und Einreichen von Aktionen werden alle kombiniert. AI muss nur die Geschäftsabsicht auswählen und muss das Formular CSS nicht immer wieder organisieren.",
