  "自动初始化。MutationObserver 同时处理新增节点和后加行为属性，适合 SPA、CMS 画布和 AI 流式生成 DOM。": "Automatische Initialisierung. MutationObserver verarbeitet gleichzeitig neue Knoten und hinzugefügte Verhaltensattribute und eignet sich für SPA, CMS Canvas und AI-Streaming zur Generierung von DOM.",
  "自动初始化与动态 DOM 观察": "Automatische Initialisierung und dynamische DOM-Beobachtung",
  "自动高度、Enter/Shift+Enter、": "Automatische Höhe, Eingabe/Umschalt+Eingabe,",
  "自动化": "Automatisierung",
  "自动生成，覆盖每个源码模块、语义类、原始选择器、Token、自定义状态钩子、数据属性和关键帧；工具类使用下一节的专用完整清单。它是源码级目录，不是精选示例。": "Automatisch generiert, deckt jedes Quellcodemodul, jede semantische Klasse, jeden primitiven Selektor, jedes Token, jeden benutzerdefinierten Status-Hook, jedes Datenattribut und jeden Keyframe ab; Verwenden Sie für Werkzeugklassen die entsprechende vollständige Liste im nächsten Abschnitt. Es handelt sich um ein Verzeichnis auf Quellebene und nicht um ein vorgestelltes Beispiel.",
  "自动推进、退格、方向键、整串粘贴、完成事件": "Auto-Advance, Backspace, Pfeiltasten, ganze String-Paste, Abschlussereignis",
  "自动完成预检与版本快照。": "Vervollständigen Sie automatisch Preflight- und Versions-Snapshots.",
