  "作为父级。列宽类保持相同，AI 只需先确定父级系统。": "als übergeordnetes Element. Die Spaltenbreitenklasse bleibt gleich, die KI muss lediglich zunächst das übergeordnete System ermitteln.",
  "作为兼容别名保留。按组件名构建时，构建器依据类选择器与": "Als kompatibler Alias ​​reserviert. Beim Erstellen nach Komponentennamen hängt der Builder vom Klassenselektor und ab",
  "作者可使用的 309 个属性被划分为上方行为契约中的 66 个行为入口、166 个结构/动作选择器和 77 个附加配置属性；另有 27 个由运行时维护的状态属性。状态属性可能同时作为初始配置读取，但作者可用的前三组彼此互斥，不会重复计数。": "Die 309 Eigenschaften, die dem Autor zur Verfügung stehen, sind in 66 Verhaltenseinträge im Verhaltensvertrag oben, 166 Struktur/Aktionsselektoren und 77 zusätzliche Konfigurationseigenschaften unterteilt; es gibt auch 27 Zustandseigenschaften, die von der Laufzeit beibehalten werden. Statuseigenschaften können gleichzeitig als erste Konfiguration gelesen werden, aber die ersten drei dem Autor zur Verfügung stehenden Sätze schließen sich gegenseitig aus und werden nicht doppelt gezählt.",
