  "Axe 门禁阻断所选 WCAG A/AA 规则检测到的全部违规，不按 impact 降级放行，并输出规则、节点选择器、HTML 与修复摘要。自动化不能代替人工屏幕阅读器测试；正式产品仍应使用 NVDA / JAWS / VoiceOver 完成关键任务走查。": "Axe Gate blockiert alle Verstöße, die durch die ausgewählten WCAG A/AA-Regeln erkannt werden, übergibt sie ohne Herabstufung durch Auswirkungen und gibt die Regel, den Knotenwähler, HTML und die Zusammenfassung zur Behebung aus. Die Automatisierung kann das Testen von menschlichen Bildschirmlesern nicht ersetzen; Produktionsprodukte sollten weiterhin NVDA/JAWS/VoiceOver für unternehmenskritische Walkthroughs verwenden.",
  "Axe WCAG 2 A/AA 全部自动违规归零，并覆盖键盘与焦点恢复、RTL、Reduced Motion、Forced Colors。": "Axe WCAG 2 A / AA Alle automatischen Verletzung Nullen und deckt Tastatur und Fokus Wiederherstellung, RTL, reduzierte Bewegung, erzwungene Farben.",
