  "Gardener": "Gardener",
  "Gardener — 为所有界面准备好的 CSS 基础设施": "Gardener — CSS-Infrastruktur bereit für alle Schnittstellen",
  "gardener / workspace / overview": "Gärtner/Arbeitsplatz/Übersicht",
  "Gardener 把基础 CSS、交互组件、业务配方、桌面端适配与机器可读清单放进同一套系统。人可以直接开发，AI 可以准确选用，无需每次重新组织样式。": "Gardener bringt grundlegendes CSS, interaktive Komponenten, Geschäftsrezepte, Desktop-Anpassung und maschinenlesbare Manifeste in ein System. Menschen können sich direkt entwickeln, und AI kann es genau auswählen und verwenden, ohne den Stil jedes Mal neu organisieren zu müssen.",
  "Gardener 可以只使用 CSS，也可以加载零依赖运行时获得交互行为。完整包默认包含所有主题、组件和工具类。": "Gardener kann nur CSS verwenden oder eine Null-Abhängigkeits-Laufzeit für interaktives Verhalten laden. Das vollständige Paket enthält standardmäßig alle Themes, Komponenten und Werkzeugklassen.",
  "Gardener 是面向人类开发者与 AI 页面生成器的通用 CSS、Vue 3、React、AngularJS 与 Blazor 组件、页面配方及桌面应用基础设施。": "Gardener ist universelle CSS, Vue 3, React, AngularJS und Blazor-Komponenten, Seitenrezepte und Desktop-Anwendungsinfrastruktur für menschliche Entwickler und KI-Seitenersteller.",
  "Gardener 首页": "Gardener Home Page",
  "Gardener 完整文档：CSS、Vue 3、React、AngularJS、Blazor、主题、Token、工具类、506 个组件、运行时、完整页面、AI 页面生成及桌面端适配。": "Gardener vollständige Dokumentation: CSS, Vue 3, React, AngularJS, Blazor, Theme, Token, Tool-Klasse, 506 Komponenten, Laufzeit, vollständige Seite, AI-Seitengenerierung und Desktop-Anpassung.",
  "Gardener 为 AI 提供五层事实来源：公共 API 清单回答“允许使用什么稳定名称与入口”，能力清单回答“行业常规能力是否实现”，组件清单回答“有什么”，工具类清单回答“精确类名是什么”，配方清单回答“复杂页面怎样开始”。": "Gardener bietet fünf Ebenen von Wahrheitsquellen für KI: Die öffentliche API-Liste beantwortet \"welche stabilen Namen und Einträge dürfen verwendet werden\", die Fähigkeitsliste beantwortet \"ob die regulären Fähigkeiten der Branche implementiert sind\", die Komponentenliste beantwortet \"was gibt es\", die Tool-Klassenliste beantwortet \"was ist der genaue Klassenname\" und die Rezeptliste beantwortet \"wie man eine komplexe Seite startet\".",
  "Gardener 文档": "Gardener Dokumentation",
