  "Public API、组件、工具类、配方与行业能力五类清单，把允许使用的名称、入口、平台、状态和响应条件结构化暴露出来，页面生成过程可以被约束、验证和复现。": "Die Fünf-Kategorie-Liste der Public API, Komponenten, Tool-Klassen, Rezepte und Branchenfähigkeiten zeigt die erlaubten Namen, Eingänge, Plattformen, Status und Antwortbedingungen in strukturierter Weise. Der Seitengenerierungsprozess kann eingeschränkt, verifiziert und reproduziert werden.",
