  "Reduced Motion": "Reduzierte Bewegung",
  "Reduced Motion 关闭 Drawer、Tree 与 Skip Link 过渡；Forced Colors 提供显式当前项轮廓；打印隐藏操作导航，保留 Breadcrumb、文档前后页与流程信息。": "Reduced Motion schaltet die Übergänge von Zeichner, Baum und Skip Link aus; Forced Colors liefert explizite aktuelle Artikelumrisse; Drucken verbirgt die Betriebsnavigation und behält Breadcrumb, Dokumentvorder- und Rückseiten und Prozessinformationen.",
  "Reduced Motion 降低保存动画；打印隐藏密码、清空、增删和提交动作，保留字段值、验证与审核信息。": "Reduced Motion reduziert die Speicheranimation; druckt versteckte Passwörter, Löschungen, Ergänzungen, Löschungen und Eingabeaktionen, behält Feldwerte, Verifizierungs- und Überwachungsinformationen.",
  "Reel": "Reel",
  "Refund Status": "Rückerstattungsstatus",
  "Registration": "Registrierung",
  "Relation Picker": "Relation Picker",
  "Release 构建为 0 警告、0 错误；506 个组件全部经过真实静态 SSR。浏览器矩阵覆盖 Chromium、Firefox、WebKit、桌面与移动视口、键盘和 Axe WCAG A/AA；CI 强制 Firefox。 NuGet 使用隔离缓存真实发布消费应用，并验证静态 Web Assets endpoint manifest；另有独立 .NET 11 Preview 包消费者。程序集实测 343,552 B，43 个静态资源共 7,608,327 B，CSS gzip 139,269 B，runtime gzip 25,989 B，Blazor bridge gzip 2,054 B，nupkg 约 1.22 MiB、低于 6,000,000 B 硬上限；全部低于硬预算且 DLL/XML 可复现。": "Release-Build mit 0 Warnungen, 0 Fehlern; 506 Komponenten haben alle den echten statischen SSR bestanden. Die Browser-Matrix umfasst Chromium, Firefox, WebKit, Desktop- und mobile Ansichtsfenster, Tastatur und Axe WCAG A/AA; CI schreibt Firefox vor. NuGet verwendet einen isolierten Cache, um Verbraucheranwendungen tatsächlich zu veröffentlichen und statische Web Assets-Endpunktmanifeste zu validieren. Es gibt auch einen eigenständigen .NET 11 Preview-Paketkonsumenten. Die gemessene Assembly ist 343.552 B, 43 statische Ressourcen insgesamt 7.608.327 B, CSS gzip 139.269 B, Laufzeit-gzip 25.989 B, Blazor Bridge gzip 2.054 B, nupkg etwa 1,22 MiB, unterhalb der harten Grenze von 6.000.000 B; alles unterhalb des harten Budgets und DLL/XML reproduzierbar.",
  "Release confidence · 1.0.0": "Vertrauen freigeben · 1.0.0",
  "Release-ready delivery · 1.0.0": "Release-ready delivery · 1.0.0",
  "Repeatable Field": "Wiederholbares Feld",
