  "Tauri v2 由应用注入 Window API；权限能力、文件系统、Updater、Deep Link、Tray 与多窗口按应用 Capability 配置，不由 CSS 自动申请。": "Tauri v2 wird von der Anwendung in die Fenster-API injiziert; Berechtigungsfunktionen, Dateisystem, Updater, Deep Link, Tray und Multi-Fenster werden gemäß der Anwendungsfunktion konfiguriert und werden nicht automatisch von CSS beantragt.",
