  "Thinking": "Denken",
  "Thinking 默认展示可读的推理摘要或进度，不要求泄露模型私有推理链；产品需明确区分“摘要”“工具日志”和“最终答案”。": "Thinking zeigt standardmäßig eine lesbare Zusammenfassung der Argumentation oder den Fortschritt an und erfordert nicht, dass die private Argumentationskette des Modells offengelegt wird; das Produkt muss klar zwischen \"Zusammenfassung\", \"Toolprotokoll\" und \"Endantwort\" unterscheiden.",
